import{_ as e,o as l,c as a,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const H=JSON.parse('{"title":"展开链讲稿 · 第三分册：谱方程与黎曼零点（Sierra-CQM 耦谱定理）","description":"","frontmatter":{},"headers":[],"relativePath":"L003_第三分册_谱方程与黎曼零点.md","filePath":"L003_第三分册_谱方程与黎曼零点.md"}'),r={name:"L003_第三分册_谱方程与黎曼零点.md"};function n(L,t,C,M,d,D){return l(),a("div",null,[...t[0]||(t[0]=[o('<div><h1 id="展开链讲稿-·-第三分册-谱方程与黎曼零点-sierra-cqm-耦谱定理" tabindex="-1">展开链讲稿 · 第三分册：谱方程与黎曼零点（Sierra-CQM 耦谱定理） <a class="header-anchor" href="#展开链讲稿-·-第三分册-谱方程与黎曼零点-sierra-cqm-耦谱定理" aria-label="Permalink to &quot;展开链讲稿 · 第三分册：谱方程与黎曼零点（Sierra-CQM 耦谱定理）&quot;">​</a></h1><blockquote><p><strong>稿子性质</strong>：本稿是<strong>撰写</strong>，不是摘录。它接续第二分册（统一群与两个常数），回答链条上紧接着的一个问题： 黎曼零点在这条链上处在什么位置，以及一个谱方程怎么把它们逼出来。</p><p><strong>它不是权威源</strong>。权威源仍是各文档原文与根 <code>README.md</code>；本稿的每一条论断都在<strong>附录 A</strong> 里钉到出处。</p><p><strong>三条写作纪律</strong>（本稿对 <code>AGENTS.md</code> 三条红线的具体执行）：</p><ol><li><strong>不欺骗</strong>——未证处不得写成已证。本稿凡涉及未闭合处，一律写明缺口编号与状态。</li><li><strong>不绕过</strong>——缺口不省略、不用&quot;因此&quot;跨过；必须跨时，句式是&quot;在缺口 X 未闭合的前提下，下游成立的是……&quot;。</li><li><strong>不虚构</strong>——只用原文已有的概念、术语、数值与关系；不引入原文未涉及的观点，也不替原文补理由（原文未展开动机处，本稿明写&quot;原文未在此处展开&quot;）。</li></ol></blockquote><hr><h2 id="卷首-·-本分册在链条上的位置" tabindex="-1">卷首 · 本分册在链条上的位置 <a class="header-anchor" href="#卷首-·-本分册在链条上的位置" aria-label="Permalink to &quot;卷首 · 本分册在链条上的位置&quot;">​</a></h2><p>第二分册停在两个常数上：$\\alpha$ 是比值型、一阶近似；$G_N$ 是有量纲特征常数、构造后验待独立复现。那两个数字的来源都指向同一片数学——<strong>黎曼零点的谱</strong>。$\\mathfrak c_1=1/4+\\gamma_1^2\\approx200.04$ 出现在 $G_N$ 公式里，$\\gamma_n$ 是&quot;第 $n$ 个黎曼零点虚部&quot;。本分册要做的，就是把这层关系从&quot;公式里出现的一个数&quot;提升为&quot;链条上一个有明确层级的环节&quot;。</p><table tabindex="0"><thead><tr><th style="text-align:left;">层</th><th style="text-align:left;">省略什么</th><th style="text-align:left;">回答什么</th><th style="text-align:left;">在哪节</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>导读层</strong></td><td style="text-align:left;">省略全部构造细节</td><td style="text-align:left;">黎曼零点在链条的哪一层，凭什么说它是&quot;共振&quot;</td><td style="text-align:left;">第一章前半、第三章前半</td></tr><tr><td style="text-align:left;"><strong>概念层</strong></td><td style="text-align:left;">省略证明，保留对象与边界条件</td><td style="text-align:left;">$L_n$、$\\vartheta_n$、Floquet 条件、耦级 $\\mathfrak c_n$</td><td style="text-align:left;">第一、二章后半</td></tr><tr><td style="text-align:left;"><strong>链条层</strong></td><td style="text-align:left;">不省略顺序，标注状态与断点</td><td style="text-align:left;">从谱算符到黎曼零点，缺口在哪里</td><td style="text-align:left;">第四、五章</td></tr><tr><td style="text-align:left;"><strong>技术层</strong></td><td style="text-align:left;">不省略任何东西</td><td style="text-align:left;">酉等价、量子化条件、误差阶、加权边界条件</td><td style="text-align:left;">指向原文 §8.1、D019 §5</td></tr></tbody></table><hr><h2 id="第一章-位置-黎曼零点在链条的哪一层" tabindex="-1">第一章 位置：黎曼零点在链条的哪一层 <a class="header-anchor" href="#第一章-位置-黎曼零点在链条的哪一层" aria-label="Permalink to &quot;第一章 位置：黎曼零点在链条的哪一层&quot;">​</a></h2><h3 id="_1-1-一个必须先说清的层级问题" tabindex="-1">1.1 一个必须先说清的层级问题 <a class="header-anchor" href="#_1-1-一个必须先说清的层级问题" aria-label="Permalink to &quot;1.1 一个必须先说清的层级问题&quot;">​</a></h3><p>原文对&quot;黎曼零点属于哪一层&quot;给了明确的分层，而这个分层极易被读混：<strong>ζ 零点谱（$L_n$、$\\vartheta_n$、$\\mathfrak{c}_n$）直接作为 GL(1) 因子层（电磁）下使用的谱</strong>；基态层的对应结构由 <strong>GL(5) 自守 $L$ 函数的零点谱</strong>给出，经<strong>紧化等价关系</strong>与各因子层谱匹配。【锚 A-31】</p><p>换句话说，链条上同时住着两种&quot;零点谱&quot;，分工不同：</p><table tabindex="0"><thead><tr><th style="text-align:left;">层</th><th style="text-align:left;">零点谱</th><th style="text-align:left;">角色</th></tr></thead><tbody><tr><td style="text-align:left;">基态层</td><td style="text-align:left;">GL(5) 自守 $L$ 函数的零点谱</td><td style="text-align:left;">SU(5) 基态同步的来源（GL(5) 固定层级的实谱条件是广义黎曼猜想）</td></tr><tr><td style="text-align:left;">GL(1) 因子层（电磁）</td><td style="text-align:left;">ζ 零点谱 $\\gamma_n$</td><td style="text-align:left;">直接作为该因子层下使用的谱；黎曼猜想是它在 GL(1) 的特例</td></tr></tbody></table><p>本分册处理的是后者——电磁因子层上的 ζ 零点谱，也就是 Sierra-CQM 耦谱定理的对象。</p><h3 id="_1-2-核心参数-三个纯数" tabindex="-1">1.2 核心参数：三个纯数 <a class="header-anchor" href="#_1-2-核心参数-三个纯数" aria-label="Permalink to &quot;1.2 核心参数：三个纯数&quot;">​</a></h3><p>与这片谱相关的核心参数，原文交代得干净：$☯=\\frac{d}{ds}\\ln\\xi(s)\\big|_{s=1}\\approx0.02309570897$，$\\mathfrak{c}_n=1/4+\\gamma_n^2$（第一耦级 $\\mathfrak c_1\\approx200.04$）——<strong>全部是无量纲数学纯数，直接来自解析数论</strong>。【锚 A-32】</p><p>这句话值得停一下：链条上绝大多数常数要么有量纲（$G_N$、$K$ 家族），要么是比值（$\\alpha$、$m_e/m_p$）；而这里的 $☯$ 与 $\\gamma_n$ 属于第三类——<strong>纯数型</strong>，谱／算术量，量纲发生学中没有对应的&quot;量纲对&quot;（量纲与群论文档 §7.5 的三分类）。它们进入物理不经过任何量纲转换，这也是后文&quot;条件性定理&quot;的数学部分能够严格的原因：它处理的本来就是纯数之间的事。</p><h3 id="_1-3-与基态层的衔接" tabindex="-1">1.3 与基态层的衔接 <a class="header-anchor" href="#_1-3-与基态层的衔接" aria-label="Permalink to &quot;1.3 与基态层的衔接&quot;">​</a></h3><p>基态层一侧，原文的表述是：前时空的基态同步是 SU(5)（来自 GL(5) 自守形式（Regge 底空间几何条件（非唯一））的紧化，基态 $L$ 函数 $L(s,\\rho_5)=\\prod_p\\det(1-\\rho_5(\\mathrm{Fr}_p)p^{-s})^{-1}$ 的零点谱）；上述 ζ 零点谱经紧化投影 $\\hat{\\mathcal S}_0$ 从 GL(5) 固定层级给出。【锚 A-31】</p><p>本稿不做的一件事：不展开 GL(5) 自守 $L$ 函数的结构（原文在此处未展开），也不比较两条零点谱的逐个对应——原文只给出&quot;经紧化等价关系与各因子层谱匹配&quot;这一层交代，本稿照抄这一层。</p><hr><h2 id="第二章-定理-一个边界条件逼出黎曼零点" tabindex="-1">第二章 定理：一个边界条件逼出黎曼零点 <a class="header-anchor" href="#第二章-定理-一个边界条件逼出黎曼零点" aria-label="Permalink to &quot;第二章 定理：一个边界条件逼出黎曼零点&quot;">​</a></h2><h3 id="_2-1-两个输入" tabindex="-1">2.1 两个输入 <a class="header-anchor" href="#_2-1-两个输入" aria-label="Permalink to &quot;2.1 两个输入&quot;">​</a></h3><p>定理的输入只有两个对象：【锚 A-33】</p><ul><li><strong>Sprinkling 区间长度</strong> $L_n=2\\pi n/\\gamma_n\\sim\\ln(n)$。原文括注了它的含义：这是 <strong>$u$-依赖的紫外截断</strong>——高耦级过程需要更小的截断；</li><li><strong>边界相位</strong> $\\vartheta_n=-\\theta\\big(\\mathfrak{c}_n^{(R)}\\big)\\pmod\\pi$。</li></ul><h3 id="_2-2-定理陈述" tabindex="-1">2.2 定理陈述 <a class="header-anchor" href="#_2-2-定理陈述" aria-label="Permalink to &quot;2.2 定理陈述&quot;">​</a></h3><p><strong>定理 8.1（Sierra-CQM）</strong>。设 Sprinkling 区间长度为 $L_n=2\\pi n/\\gamma_n$，边界相位为 $\\vartheta_n$。则 $\\hat H=\\hat D^2+1/4$ 在 $[0,L_n]$ 上的<strong>耦级</strong>满足：</p><p>$$\\mathfrak{c}_n^{(R)}=\\frac{1}{4}+\\gamma_n^2+O\\!\\left(\\frac{\\gamma_n^2}{n}\\right)$$</p><p>相对误差 $O(1/n)$，当 $n\\to\\infty$ 时趋于零。其中 $\\gamma_n$ 是第 $n$ 个黎曼零点虚部。【锚 A-33】</p><h3 id="_2-3-证明第一步-酉等价化简" tabindex="-1">2.3 证明第一步：酉等价化简 <a class="header-anchor" href="#_2-3-证明第一步-酉等价化简" aria-label="Permalink to &quot;2.3 证明第一步：酉等价化简&quot;">​</a></h3><p>通过酉映射 $U:f\\mapsto e^{-u/2}f$，算符 $\\hat H=-\\partial_u^2+\\partial_u$ 在 $L^2(e^{-u}du)$ 中酉等价于 $\\tilde A=-\\partial_u^2+1/4$ 在 $L^2(du)$ 中。在 $L^2(du)$ 中，算符 $-\\partial_u^2$ 的标准本征函数为平面波 $g_k(u)=e^{iku}$，对应本征值 $k^2$。【锚 A-34】</p><p>这一步的数学内容（保内积的验证与算符变换的计算）在 D019 中有完整展开，结论一致。【锚 A-35】</p><h3 id="_2-4-证明第二步-floquet-边界条件" tabindex="-1">2.4 证明第二步：Floquet 边界条件 <a class="header-anchor" href="#_2-4-证明第二步-floquet-边界条件" aria-label="Permalink to &quot;2.4 证明第二步：Floquet 边界条件&quot;">​</a></h3><p>对 $g_k(u)=e^{iku}$ 施加 Floquet（拟周期）边界条件：</p><p>$$g_k(L_n)=e^{i\\vartheta_n}g_k(0),\\qquad g_k\'(L_n)=e^{i\\vartheta_n}g_k\'(0)$$</p><p>原文紧接着给了自伴性的判据：该边界条件对 $-\\partial_u^2$ 是自伴的（边界项 $[-f^*g\'+f\'^*g]_0^{L_n}=0$ 直接验证）。量子化条件为 $e^{ikL_n}=e^{i\\vartheta_n}$，即 $kL_n=\\vartheta_n+2\\pi m$（$m\\in\\mathbb Z$）。【锚 A-34】</p><h3 id="_2-5-证明第三、四步-零点匹配与耦级计算" tabindex="-1">2.5 证明第三、四步：零点匹配与耦级计算 <a class="header-anchor" href="#_2-5-证明第三、四步-零点匹配与耦级计算" aria-label="Permalink to &quot;2.5 证明第三、四步：零点匹配与耦级计算&quot;">​</a></h3><p>设 $L_n=2\\pi n/\\gamma_n$，对 $m=n$：</p><p>$$k_n=\\frac{2\\pi n+\\vartheta_n}{L_n}=\\gamma_n\\left(1+\\frac{\\vartheta_n}{2\\pi n}\\right)$$</p><p>由于 $\\vartheta_n\\in[0,\\pi)$ 有界，$k_n=\\gamma_n+O(1/n)$。$\\tilde A$ 的本征值为 $k_n^2+1/4$，对应 $\\hat H$ 的耦级：</p><p>$$\\mathfrak{c}_n^{(R)}=k_n^2+\\frac{1}{4}=\\gamma_n^2+\\frac{1}{4}+O\\!\\left(\\frac{\\gamma_n^2}{n}\\right)$$</p><p>D019 补了一个集成理论摘要中没有的细节，值得一并记住：绝对误差项 $O(\\gamma_n^2/n)$ 随 $n$ <strong>增长</strong>（因为 $\\gamma_n\\sim2\\pi n/\\log n$，Riemann–von Mangoldt 公式 $N(T)\\sim T\\log T/(2\\pi)$ 的推论），<strong>相对</strong>误差 $O(1/n)$ 才趋于零。【锚 A-35】</p><h3 id="_2-6-证明第五步-映射回-的加权边界条件" tabindex="-1">2.6 证明第五步：映射回 $L^2(e^{-u}du)$ 的加权边界条件 <a class="header-anchor" href="#_2-6-证明第五步-映射回-的加权边界条件" aria-label="Permalink to &quot;2.6 证明第五步：映射回 $L^2(e^{-u}du)$ 的加权边界条件&quot;">​</a></h3><p>本征函数为 $f_k(u)=e^{u/2}g_k(u)=e^{(1/2+ik)u}$，边界条件映射为<strong>加权 Floquet 条件</strong>：</p><p>$$f_k(L_n)=e^{L_n/2}e^{i\\vartheta_n}f_k(0)$$</p><p>原文说明：该条件对 $\\hat H$ 在 $L^2(e^{-u}du)$ 中自伴，振幅因子 $e^{L_n/2}$ 来自测度变换的 Jacobian。【锚 A-34】</p><p>至此五步走完，$\\square$。本稿提醒一句读法：整条证明的&quot;严格部分&quot;到这一步为止——第二、三章之后的内容（第四章）全部是在说这些步骤里哪些是数学、哪些是构造。</p><hr><h2 id="第三章-诠释-零点-再生产过程的共振模式" tabindex="-1">第三章 诠释：零点 = 再生产过程的共振模式 <a class="header-anchor" href="#第三章-诠释-零点-再生产过程的共振模式" aria-label="Permalink to &quot;第三章 诠释：零点 = 再生产过程的共振模式&quot;">​</a></h2><h3 id="_3-1-共振图像" tabindex="-1">3.1 共振图像 <a class="header-anchor" href="#_3-1-共振图像" aria-label="Permalink to &quot;3.1 共振图像&quot;">​</a></h3><p>原文给的物理诠释只有一段，但它是本分册的心脏：<strong>黎曼零点对应于&quot;再生产过程的共振模式&quot;</strong>。每个零点 $\\gamma_n$ 对应特定的 Sprinkling 区间长度 $L_n$，由相位匹配条件确保共振。【锚 A-36】</p><p>用第一分册的语言翻译（翻译本身不是原文论断，请回查原文）：再生产是物质自组织维持自身的一个环节；说零点是&quot;共振模式&quot;，等于说第 $n$ 个零点标记了一段再生产过程与边界条件达成相位匹配的尺度 $L_n$。原文未在此处展开&quot;再生产&quot;与谱算符本征值之间的进一步机制——超导文档中的同步算符体系是另一条更长的线（见第四章末与第五分册的衔接）。</p><h3 id="_3-2-振幅因子-的几何意义" tabindex="-1">3.2 振幅因子 $e^{L_n/2}$ 的几何意义 <a class="header-anchor" href="#_3-2-振幅因子-的几何意义" aria-label="Permalink to &quot;3.2 振幅因子 $e^{L_n/2}$ 的几何意义&quot;">​</a></h3><p>加权边界条件中的振幅因子 $e^{L_n/2}$，原文的解释是：它反映了<strong>耦合空间测度 $e^{-u}du$ 对边界模式的指数调制</strong>——这是因果集 Sprinkling 在耦合空间中的几何效应。【锚 A-36】</p><p>这句话的分量在于：$e^{-u}du$ 不是外加的积分测度，它是第一分册第二章里由 Sprinkling 逼出来的测度。边界条件&quot;知道&quot;这个测度（通过 Jacobian），等于说谱的量子化条件里带着耦合空间几何的印记。</p><hr><h2 id="第四章-成色-一个条件性定理" tabindex="-1">第四章 成色：一个条件性定理 <a class="header-anchor" href="#第四章-成色-一个条件性定理" aria-label="Permalink to &quot;第四章 成色：一个条件性定理&quot;">​</a></h2><h3 id="_4-1-哪些步骤严格-哪些步骤构造性" tabindex="-1">4.1 哪些步骤严格，哪些步骤构造性 <a class="header-anchor" href="#_4-1-哪些步骤严格-哪些步骤构造性" aria-label="Permalink to &quot;4.1 哪些步骤严格，哪些步骤构造性&quot;">​</a></h3><p>D019 对同一个定理做了严格性评估，评估结论与原文献擎互相印证，必须整段保留：<strong>步骤 1–3 的数学推导是严格的</strong>（酉等价、平面波、Floquet 边界条件）；<strong>步骤 4 中 $L_n=2\\pi n/\\gamma_n$ 的选择是构造性的</strong>——它被设计为使 $k_n\\approx\\gamma_n$，其物理来源（为何 Sprinkling 区间长度与第 $n$ 个黎曼零点成反比）尚未从第一性原理导出；<strong>$m=n$ 的选择也是构造性的</strong>。因此，此定理是&quot;<strong>条件性定理</strong>&quot;——如果接受 $L_n$ 和 $m=n$ 的选择，则结论严格成立。【锚 A-35】</p><p>集成理论原文在同一位置有一个短注，口径相同：$m=n$ 的选择是一种构造性对应；$L_n$ 的物理来源与 $\\vartheta_n$ 的严格推导是当前严格性缺口。【锚 A-37】</p><blockquote><p><strong>断点（就地标出）</strong>：$L_n$ 的物理来源与 $\\vartheta_n$ 的严格推导——<strong>未闭合</strong>（集成理论 §8.1 注记为&quot;当前严格性缺口&quot;）。因此本分册第二章的全部结论都以&quot;接受 $L_n=2\\pi n/\\gamma_n$ 与 $m=n$&quot;为前提：这是<strong>条件性定理</strong>，不是无前提定理。凡下游引用 $\\mathfrak c_n=1/4+\\gamma_n^2$ 处（如第二分册 $G_N$ 公式中的 $\\mathfrak c_1$），继承的正是这个条件。【锚 A-37】</p></blockquote><h3 id="_4-2-lean-形式化状态" tabindex="-1">4.2 Lean 形式化状态 <a class="header-anchor" href="#_4-2-lean-形式化状态" aria-label="Permalink to &quot;4.2 Lean 形式化状态&quot;">​</a></h3><p>同一份文档登记了形式化状态：步骤 4–5 的代数核心已在 <code>GN/SierraCQM.lean</code> 形式化（<strong>6 个定理，零 <code>sorry</code></strong>）——零点匹配、偏差界 $|k_n-\\gamma_n|<\\gamma_n/(2n)$、耦级绝对/相对误差（含 $n\\ge1$ 时见证常数 $5/4$）；$L_n$ 与 $m=n$ 以<strong>显式假设</strong>出现。步骤 1–2（酉等价、平面波广义本征函数）需函数空间算子与分布谱论基础设施，<strong>未形式化</strong>。【锚 A-35】</p><p>注意 Lean 状态与断点的关系恰好互相印证：形式化覆盖的正是代数核心，而两个构造性选择以显式假设的身份进入证明——机器没有、也不打算替我们补上它们的物理来源。</p><h3 id="_4-3-与外部文献的关系" tabindex="-1">4.3 与外部文献的关系 <a class="header-anchor" href="#_4-3-与外部文献的关系" aria-label="Permalink to &quot;4.3 与外部文献的关系&quot;">​</a></h3><p>原文参考文献中与本分册直接相关的有三条：Sierra (2008) 的黎曼零点量子力学模型、Berry–Keating (1999) 的零点与本征值渐近、Endres–Steiner (2010) 关于 Berry–Keating 算符在 $L^2(\\mathbb R_>,dx)$ 上谱纯连续、亏指数 $(0,0)$ 的结果。【锚 A-38】</p><p>本稿对这三条文献的交代仅止于&quot;原文如此引用&quot;：本稿未核对外部文献的原始内容，也不判断 CQM 构造与它们的数学关系——那超出本稿的六关范围（出处存在一关由原文承担）。</p><hr><h2 id="第五章-本体论-黎曼猜想在这条链上的地位" tabindex="-1">第五章 本体论：黎曼猜想在这条链上的地位 <a class="header-anchor" href="#第五章-本体论-黎曼猜想在这条链上的地位" aria-label="Permalink to &quot;第五章 本体论：黎曼猜想在这条链上的地位&quot;">​</a></h2><h3 id="_5-1-等价链" tabindex="-1">5.1 等价链 <a class="header-anchor" href="#_5-1-等价链" aria-label="Permalink to &quot;5.1 等价链&quot;">​</a></h3><p>集成理论第十三部分把黎曼猜想的地位写成一条等价链：【锚 A-39】</p><p>$$\\text{GL(5) 固定层级的零点猜想（GRH）}\\iff\\text{配对不变量 }\\mathfrak c_n\\text{ 为实}\\iff\\text{物质同步稳定}\\iff\\text{有限化可能}\\iff\\text{规范群可涌现}\\iff\\text{结构群叠加态存在}$$</p><p>原文的解释：如果 GL(5) 固定层级的零点猜想不成立，配对不变量 $\\mathfrak c_n$ 不为实，物质无法稳定同步，质子/中子不能有限化，$A_4$ 不能涌现，规范群不能组织，结构群叠加态无从谈起。<strong>GL(5) 固定层级的零点猜想构成所有结构群可能性的最终存在论前提</strong>；黎曼猜想（GL(1) 电磁因子层的实谱条件）直接进入超导相变判据（$T_c$），是该层级直接可观测的稳定性条件。</p><h3 id="_5-2-假说性等价-不是已证等价" tabindex="-1">5.2 假说性等价，不是已证等价 <a class="header-anchor" href="#_5-2-假说性等价-不是已证等价" aria-label="Permalink to &quot;5.2 假说性等价，不是已证等价&quot;">​</a></h3><p>这条链上的每一个 $\\iff$ 都必须连着限定语念，删掉限定语整段话的性质就变了。原文的注写明：上式中的 $\\iff$ 表示<strong>框架内假说性等价</strong>——各环节依赖 CQM 构造假设与未证核心定理（如 §7.1 的&quot;退相干稳态是正四单纯形&quot;、§8.1 的紧化投影），<strong>非已证逻辑等价</strong>；其中&quot;配对不变量为实 $\\iff$ 零点在临界线&quot;一步为<strong>纯代数等价</strong>。【锚 A-39】</p><p>也就是说，一条六环的链里，只有一环是已证的代数事实，其余五环都是框架内假说。本稿不做的事：不把这条链读成&quot;黎曼猜想被 CQM 证明了&quot;或&quot;黎曼猜想被 CQM 需要&quot;——原文的定位是前者（框架内假说性等价），既不是证明，也不是公理。</p><h3 id="_5-3-往下一环的交接" tabindex="-1">5.3 往下一环的交接 <a class="header-anchor" href="#_5-3-往下一环的交接" aria-label="Permalink to &quot;5.3 往下一环的交接&quot;">​</a></h3><p>黎曼猜想在这条链上的出口在超导：它是 GL(1) 电磁因子层的实谱条件，直接进入超导相变判据 $T_c$（第十三部分 §13.16）。下一分册处理超导涌现链时，这条线会以&quot;同步算符本征值与 $T_c$&quot;的形式回来——那是一片比本册密得多的断点带。</p><hr><h2 id="附录-a-·-锚点表" tabindex="-1">附录 A · 锚点表 <a class="header-anchor" href="#附录-a-·-锚点表" aria-label="Permalink to &quot;附录 A · 锚点表&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">锚</th><th style="text-align:left;">论断摘要</th><th style="text-align:left;">出处</th><th style="text-align:left;">定位</th><th style="text-align:left;">核对状态</th></tr></thead><tbody><tr><td style="text-align:left;">A-31</td><td style="text-align:left;">ζ 零点谱作为 GL(1) 因子层（电磁）下使用的谱；基态层由 GL(5) 自守 $L$ 函数零点谱给出、经紧化等价关系匹配；紧化投影 $\\hat{\\mathcal S}_0$</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_集成理论.md</code></td><td style="text-align:left;">第八部分层级定位注、§9.2 分层定位</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-32</td><td style="text-align:left;">$☯\\approx0.02309570897$、$\\mathfrak c_n=1/4+\\gamma_n^2$、$\\mathfrak c_1\\approx200.04$，&quot;无量纲数学纯数，直接来自解析数论&quot;</td><td style="text-align:left;">同上</td><td style="text-align:left;">§9.2</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-33</td><td style="text-align:left;">定理 8.1（Sierra-CQM）：$L_n=2\\pi n/\\gamma_n\\sim\\ln n$、$\\vartheta_n=-\\theta(\\mathfrak c_n^{(R)})\\pmod\\pi$、$\\mathfrak c_n^{(R)}=1/4+\\gamma_n^2+O(\\gamma_n^2/n)$、$u$-依赖紫外截断</td><td style="text-align:left;">同上</td><td style="text-align:left;">§8.1</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-34</td><td style="text-align:left;">五步证明：酉等价、Floquet 自伴性与量子化条件、$k_n=\\gamma_n+O(1/n)$、耦级计算、加权 Floquet 条件与 Jacobian</td><td style="text-align:left;">同上</td><td style="text-align:left;">§8.1 证明概要</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-35</td><td style="text-align:left;">D019 严格性评估（条件性定理）、$\\gamma_n\\sim2\\pi n/\\log n$ 与相对/绝对误差之别、Lean 状态（6 定理零 <code>sorry</code>、显式假设、步骤 1–2 未形式化）</td><td style="text-align:left;"><code>04 前沿研究/CQM_前沿研究_GN第一性推导_公理化证明稿.md</code></td><td style="text-align:left;">§5</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-36</td><td style="text-align:left;">物理诠释：零点＝再生产过程共振模式；振幅因子 $e^{L_n/2}$ 与测度 $e^{-u}du$ 的指数调制</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_集成理论.md</code></td><td style="text-align:left;">§8.1 物理诠释</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-37</td><td style="text-align:left;">&quot;$m=n$ 构造性对应；$L_n$ 物理来源与 $\\vartheta_n$ 严格推导是当前严格性缺口&quot;</td><td style="text-align:left;">同上</td><td style="text-align:left;">§8.1 注</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-38</td><td style="text-align:left;">外部文献三条（Sierra 2008、Berry–Keating 1999、Endres–Steiner 2010）</td><td style="text-align:left;">同上</td><td style="text-align:left;">参考文献 6、8、9</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-39</td><td style="text-align:left;">GRH $\\iff$ 链及其&quot;框架内假说性等价&quot;限定、纯代数等价一步、黎曼猜想进入 $T_c$ 判据</td><td style="text-align:left;">同上</td><td style="text-align:left;">§13.16</td><td style="text-align:left;">逐字核对</td></tr></tbody></table><h2 id="附录-b-·-六关自检-本稿口径" tabindex="-1">附录 B · 六关自检（本稿口径） <a class="header-anchor" href="#附录-b-·-六关自检-本稿口径" aria-label="Permalink to &quot;附录 B · 六关自检（本稿口径）&quot;">​</a></h2><p>沿用第一分册附录 B 的六关：出处存在／对象正确／段落相关／论断被支撑／<strong>限定语保留</strong>／来源适配。本分册的限定语集中在四处，写作时逐处核对：</p><ol><li>定理 8.1 的&quot;<strong>条件性</strong>&quot;——$L_n$ 与 $m=n$ 是构造性选择，不是推导结果（A-35、A-37）；</li><li>误差阶的&quot;<strong>相对</strong> $O(1/n)$&quot;——绝对误差 $O(\\gamma_n^2/n)$ 随 $n$ 增长，两个口径不可互换（A-35）；</li><li>GRH 等价链的&quot;<strong>框架内假说性等价</strong>&quot;——只有&quot;配对不变量为实 $\\iff$ 零点在临界线&quot;一环是纯代数等价（A-39）；</li><li>核心参数的&quot;<strong>纯数型</strong>&quot;——$☯$、$\\gamma_n$ 不经过量纲转换，不属于 $K$ 家族或比值型（A-32）。</li></ol><h2 id="附录-c-·-下一分册" tabindex="-1">附录 C · 下一分册 <a class="header-anchor" href="#附录-c-·-下一分册" aria-label="Permalink to &quot;附录 C · 下一分册&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">分册</th><th style="text-align:left;">覆盖链条段</th><th style="text-align:left;">主要依据</th></tr></thead><tbody><tr><td style="text-align:left;">第四分册</td><td style="text-align:left;">超导涌现链（跃迁耦级谱、自由能竞争与 $T_c$），含 G9–G22 断点</td><td style="text-align:left;"><code>集成理论</code> 第十一部分；<code>06 超导/CQM_超导_专题与扩展.md</code> §13</td></tr><tr><td style="text-align:left;">第五分册</td><td style="text-align:left;">与标准理论的关系、纤维丛结构与涨落伴丛</td><td style="text-align:left;"><code>集成理论</code> 第十二、十三部分</td></tr><tr><td style="text-align:left;">第六分册</td><td style="text-align:left;">量纲发生学专章（$K$ 家族逐项、自守形式猜想）</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_量纲与群论.md</code> §六、§七</td></tr></tbody></table></div>',1)])])}const i=e(r,[["render",n]]);export{H as __pageData,i as default};
